const key='algobuzz-history-v1';const store={get(){try{return JSON.parse(localStorage.getItem(key))||[]}catch{return []}},put(item){const a=this.get();a.unshift({...item,id:Date.now(),date:new Date().toISOString()});localStorage.setItem(key,JSON.stringify(a.slice(0,100)));toast('Simulation saved to history')},clear(){localStorage.removeItem(key)}};
let cpuRows=[{id:'P1',arrival:0,burst:5,priority:2},{id:'P2',arrival:1,burst:3,priority:1},{id:'P3',arrival:2,burst:6,priority:3}],cpuAlg='FCFS',quantum=2,cpuResult=null,cpuStep=0;
let allocation=[[0,1,0],[2,0,0],[3,0,2],[2,1,1],[0,0,2]],maximum=[[7,5,3],[3,2,2],[9,0,2],[2,2,2],[4,3,3]],available=[3,3,2],bankResult=null,bankStep=0,bankMode='safety';
