function route(){stop();if(location.hash!=='#/sync')stopSyncWorkers();let page=location.hash.replace('#/','')||'home';document.title=`${titles[page]||'Interactive Algorithm Visualizer'} | Algobuzz`;$('#app').innerHTML=page==='home'?landing():shell(page);if(page==='cpu')renderCPU();if(page==='sync')renderSync();if(page==='memory')renderMemory();if(page==='banker')renderBanker();if(page==='history')renderHistory();if(page==='dashboard')renderDashboard();if(page==='quiz')renderQuiz();}
function logo(){return `<a class="logo" href="#/home"><span class="logo-mark">⌘</span><span>Algo<b>buzz</b></span></a>`}
function landing(){return `<header class="site-header">${logo()}<nav class="site-links"><a href="#/home">Home</a><a href="#/dashboard">Dashboard</a><a href="#/history">History</a></nav><div class="head-actions"><button class="btn ghost small" onclick="toggleTheme()">◐ Theme</button><a class="btn primary" href="#/dashboard">Start exploring ↗</a></div></header><main><section class="hero"><div><div class="eyebrow">✦ ALGOBUZZ · INTERACTIVE SIMULATIONS</div><h1>Watch every decision. <em>Understand every algorithm.</em></h1><p>Watch railway requests compete for CPU time, move through synchronized queues, request shared resources safely, and occupy memory partitions. Start a simulation and see each decision unfold before the final results appear.</p><div class="hero-actions"><a class="btn primary" href="#/dashboard">Explore simulations →</a><a class="btn ghost" href="#/cpu">Watch an algorithm run ↗</a></div><div class="hero-stats"><div><strong>4</strong><span>Interactive simulators</span></div><div><strong>Step-by-step</strong><span>Visual simulations</span></div><div><strong>100%</strong><span>Browser-based</span></div></div></div><div class="hero-art"><div class="orb"><div class="orb-inner">⌘</div></div><div class="float-tag tag1">▥ CPU Scheduling</div><div class="float-tag tag2">◇ Banker’s Algorithm</div><div class="float-tag tag3">▦ Memory Allocation</div></div></section><section class="section"><div class="panel scenario-panel"><div class="eyebrow">PROJECT CASE STUDY</div><h3>Railway Reservation and Ticket Processing System</h3><p class="sub">Model ticket booking, cancellation, payment verification, and seat-status updates using four coordinated OS concepts. This is an educational simulation; it does not book real tickets or process payments.</p></div><div class="eyebrow">EXPLORE THE SIMULATORS</div><h2>Four systems. Every step made visible.</h2><p class="section-intro">Press Start once and watch the timeline animate automatically. Pause, rewind, inspect a decision, and review the calculations and final result tables when execution completes.</p><div class="feature-grid"><a href="#/cpu" class="feature"><div class="symbol">▥</div><h3>CPU Scheduling</h3><p>FCFS, SJF, SRTF, Priority and Round Robin with animated Gantt charts.</p><strong>Open simulator →</strong></a><a href="#/sync" class="feature"><div class="symbol">⇄</div><h3>Process Synchronization</h3><p>Watch railway requests arrive at a station, queue in the bounded buffer, and depart for processing. Choose automatic or manual semaphore playback.</p><strong>Open simulator →</strong></a><a href="#/banker" class="feature"><div class="symbol">◇</div><h3>Deadlock Avoidance</h3><p>Watch the Need matrix, Work vector and process states update step by step before the safety verdict appears.</p><strong>Open simulator →</strong></a><a href="#/memory" class="feature"><div class="symbol">▦</div><h3>Memory Management</h3><p>Watch each railway process receive a partition using First Fit, Best Fit or Worst Fit, then inspect fragmentation and allocation tables.</p><strong>Open simulator →</strong></a></div></section><section class="section"><div class="eyebrow">BUILT FOR LEARNING</div><h2>Pause. Inspect. Understand.</h2><div class="feature-grid"><div class="feature"><div class="symbol">▷</div><h3>Step-by-step playback</h3><p>Advance through each operation and inspect the current state.</p></div><div class="feature"><div class="symbol">▤</div><h3>Saved experiments</h3><p>Keep a local history of simulations and export results as CSV.</p></div><div class="feature"><div class="symbol">✧</div><h3>Evaluator-ready demos</h3><p>Start with sample inputs, run the simulation, and explain the result.</p></div></div></section></main><footer class="footer"><span>© 2026 Algobuzz · Built for curious minds</span><span>Simulate · Visualize · Understand</span></footer>`}
const nav=[['dashboard','◫','Dashboard'],['cpu','▥','CPU Scheduling'],['sync','⇄','Process Synchronization'],['banker','◇',"Banker's Algorithm"],['memory','▦','Memory Management'],['history','◷','History'],['quiz','✧','Quiz']];
function shell(page){return `<div class="app-shell"><aside class="sidebar">${logo()}<div class="nav-label">SIMULATIONS</div><nav class="nav-items">${nav.map(([id,ic,label])=>`<a class="nav-link ${page===id?'active':''}" href="#/${id}"><span>${ic}</span>${label}</a>`).join('')}</nav><div class="sidebar-bottom">● All simulations run in your browser.<br>Data stays on this device.<br><br><a href="#/home">← Back to website</a></div></aside><div class="main"><header class="app-top"><h2>${titles[page]||'Workspace'}</h2><div class="top-right"><span class="pill">● ENGINE READY</span><button class="btn ghost small" onclick="toggleTheme()">◐ Theme</button></div></header><main class="page" id="content"></main></div></div>`}
function toggleTheme(){document.body.classList.toggle('light');localStorage.setItem('algobuzz-theme',document.body.classList.contains('light')?'light':'dark')}
function renderDashboard(){const h=store.get();$('#content').innerHTML=`<h1 class="page-title">Simulation dashboard</h1><p class="sub">Railway Reservation and Ticket Processing System · sample requests only, no real bookings or payments.</p><div class="scenario-strip"><strong>Case-study workflow</strong><span>Request → bounded buffer → CPU scheduling → Banker’s safety check → memory allocation → simulated result → release resources</span></div><div class="stats-grid"><div class="stat"><small>Total simulations</small><strong>${h.length}</strong></div><div class="stat"><small>Interactive simulators</small><strong>04</strong></div><div class="stat"><small>Topics covered</small><strong>Scheduling · Sync · Deadlock · Memory</strong></div><div class="stat"><small>Runs saved locally</small><strong>${h.length}</strong></div></div><h3>Launch a simulator</h3><div class="card-grid">${[['cpu','▥','CPU Scheduling','Compare scheduling algorithms using an animated Gantt chart.'],['sync','⇄','Process Synchronization','Step through Producer–Consumer operations and semaphore states.'],['banker','◇',"Deadlock Avoidance using Banker’s Algorithm",'Inspect resource matrices and safe sequences.'],['memory','▦','Memory Management','Simulate fixed and variable partition allocation and fragmentation.']].map(x=>`<div class="module-card"><div class="symbol">${x[1]}</div><h3>${x[2]}</h3><p>${x[3]}</p><a class="btn primary small" href="#/${x[0]}">Open simulator →</a></div>`).join('')}</div><div class="grid-2" style="margin-top:20px"><section class="panel"><h3>Recent activity</h3>${h.length?h.slice(0,4).map(x=>`<div class="history-item"><div><strong>${esc(x.algorithm)}</strong><small>${new Date(x.date).toLocaleString()}</small></div><a class="btn small" href="#/history">View →</a></div>`).join(''):'<div class="empty">No saved simulations yet. Run your first simulation!</div>'}</section><section class="panel"><h3>Getting started</h3><p class="sub">1. Open a simulator.<br>2. Use sample data or enter your own values.<br>3. Run the simulation and step through the states.<br>4. Save your experiment to history.</p><a class="btn ghost" href="#/history">View simulation history →</a></section></div>`}
function stop(){if(timer){clearInterval(timer);timer=null}}function play(kind){stop();const data=kind==='cpu'?cpuResult:kind==='memory'?memResult:kind==='sync'?syncResult:bankResult;if(!data){toast('Run the simulation first');return}timer=setInterval(()=>{const step=kind==='cpu'?cpuStep:kind==='memory'?memStep:kind==='sync'?syncStep:bankStep;if(step>=data.steps.length-1){stop();return}setStep(kind,step+1)},Math.max(140,850/speed));timer.kind=kind;if(kind==='cpu')drawCPU();else if(kind==='memory')drawMemory();else if(kind==='sync')drawSync();else drawBanker();}
function setStep(kind,n){const d=kind==='cpu'?cpuResult:kind==='memory'?memResult:kind==='sync'?syncResult:bankResult;if(!d)return;const v=Math.max(0,Math.min(d.steps.length-1,n));if(kind==='cpu'){cpuStep=v;drawCPU()}else if(kind==='memory'){memStep=v;drawMemory()}else if(kind==='sync'){syncStep=v;drawSync()}else{bankStep=v;drawBanker()}}
function speedSet(v){speed=+v;document.querySelectorAll('.speed-value').forEach(x=>x.textContent=`${speed}×`);if(timer){const k=timer.kind;stop();if(k)play(k)}}
function controls(kind,n,max){return `<div class="controls"><button class="btn small" onclick="stop();setStep('${kind}',0)" title="Restart">↺</button><button class="btn small" onclick="stop();setStep('${kind}',${n-1})" title="Previous">◀</button><button class="btn primary small" onclick="${timer?'stop()':`play('${kind}')`}">${timer?'Ⅱ Pause':'▶ Play'}</button><button class="btn small" onclick="stop();setStep('${kind}',${n+1})" title="Next">▶|</button><button class="btn small" onclick="stop();setStep('${kind}',${max})" title="Finish">⇥</button><label class="note">Speed <span class="speed-value">${speed}×</span></label><input type="range" min="0.5" max="3" step="0.5" value="${speed}" oninput="speedSet(this.value)"><span class="note">Step ${n}/${max}</span></div>`}
function cpuCompute(rows,alg,q){if(!rows.length||rows.length>30)throw Error('Enter between 1 and 30 processes');if(rows.some(p=>!Number.isInteger(p.arrival)||p.arrival<0||!Number.isInteger(p.burst)||p.burst<1||p.burst>100||!Number.isInteger(p.priority)))throw Error('Arrival ≥ 0, burst 1–100, priority integer');if(q<1||!Number.isInteger(q))throw Error('Time quantum must be a positive integer');let jobs=rows.map((p,i)=>({...p,order:i,remaining:p.burst,start:null,completion:null}));let steps=[{time:0,active:null,queue:[],remaining:jobs.map(x=>x.remaining),note:'Simulation ready. Advance to see the first CPU time unit.'}],gantt=[],t=0,done=0,current=null,rr=[],added=new Set(),guard=0;const pre=['SRTF','Priority (Preemptive)'].includes(alg);const nonpre=['FCFS','SJF','Priority (Non-Preemptive)'].includes(alg);let slice=0;
while(done<jobs.length&&guard++<20000){const arrived=jobs.filter(j=>j.arrival<=t&&j.remaining>0);if(alg==='Round Robin'){jobs.filter(j=>j.arrival<=t&&!added.has(j.id)).sort((a,b)=>a.arrival-b.arrival||a.order-b.order).forEach(j=>{rr.push(j);added.add(j.id)});if(!current){current=rr.shift()||null;slice=0}}else if(!current||pre){const sorted=arrived.slice().sort((a,b)=>alg==='FCFS'?a.arrival-b.arrival||a.order-b.order:alg.startsWith('SJF')||alg==='SRTF'?(alg==='SRTF'?a.remaining-b.remaining:a.burst-b.burst)||a.arrival-b.arrival||a.order-b.order:a.priority-b.priority||a.arrival-b.arrival||a.order-b.order);current=sorted[0]||null}
if(!current){const next=Math.min(...jobs.filter(j=>j.remaining>0).map(j=>j.arrival));if(!Number.isFinite(next))break;const old=t;t++;gantt.push({id:'Idle',start:old,end:t});steps.push({time:t,active:'Idle',queue:[],remaining:jobs.map(x=>x.remaining),note:`At t=${old}, no process is ready; CPU stays idle.`});continue}
const old=t;if(current.start===null)current.start=t;current.remaining--;t++;slice++;gantt.push({id:current.id,start:old,end:t});const finished=current.remaining===0;if(finished){current.completion=t;done++}
if(alg==='Round Robin'){jobs.filter(j=>j.arrival<=t&&!added.has(j.id)).sort((a,b)=>a.arrival-b.arrival||a.order-b.order).forEach(j=>{rr.push(j);added.add(j.id)});if(finished){current=null;slice=0}else if(slice>=q){rr.push(current);current=null;slice=0}}
const queue=alg==='Round Robin'?rr.map(x=>x.id):jobs.filter(j=>j.arrival<=t&&j.remaining>0&&j!==current).map(j=>j.id);steps.push({time:t,active:gantt[gantt.length-1].id,queue,remaining:jobs.map(x=>x.remaining),note:`t=${old} → ${t}: ${gantt[gantt.length-1].id} executes for one unit.${finished?' Process completes.':''} ${alg==='Round Robin'?'Quantum = '+q+'.':alg+' scheduling.'}`});if(nonpre&&finished)current=null}
if(guard>=20000)throw Error('Simulation limit exceeded');const result=jobs.map(j=>({...j,turnaround:j.completion-j.arrival,waiting:j.completion-j.arrival-j.burst,response:j.start-j.arrival}));return {steps,gantt,jobs:result,avgWait:result.reduce((a,j)=>a+j.waiting,0)/result.length,avgTat:result.reduce((a,j)=>a+j.turnaround,0)/result.length}}
function renderCPU(){stop();$('#content').innerHTML=`<h1 class="page-title">CPU Scheduling Simulator</h1><p class="sub">Railway booking, cancellation, and payment tasks compete for CPU time. Observe each CPU tick and ready-queue transition.</p><div class="tabs">${['FCFS','SJF','SRTF','Round Robin','Priority (Non-Preemptive)','Priority (Preemptive)'].map(a=>`<button class="tab ${a===cpuAlg?'active':''}" onclick="cpuAlg=${JSON.stringify(a).replace(/"/g,'&quot;')};cpuResult=null;renderCPU()">${a}</button>`).join('')}</div><div class="sim-grid"><section class="panel"><h3>Process configuration</h3><div class="table-wrap"><table><thead><tr><th>Process</th><th>Arrival</th><th>Burst</th><th>Priority</th><th></th></tr></thead><tbody id="cpu-input"></tbody></table></div><div class="action-row"><button class="btn small" onclick="cpuRows.push({id:'P'+(Math.max(0,...cpuRows.map(x=>+x.id.slice(1)))+1),arrival:0,burst:3,priority:1});renderCPU()">+ Add process</button><button class="btn small" onclick="cpuRows=[{id:'P1',arrival:0,burst:5,priority:2},{id:'P2',arrival:1,burst:3,priority:1},{id:'P3',arrival:2,burst:6,priority:3}];renderCPU()">Load example</button></div>${cpuAlg==='Round Robin'?`<div class="field"><label>Time quantum</label><input type="number" min="1" value="${quantum}" onchange="quantum=+this.value"></div>`:''}<div class="action-row"><button class="btn primary" onclick="runCPU()">▶ Start simulation</button><button class="btn" onclick="saveCPU()">Save run</button></div><p class="note">Lower priority number means higher priority. SJF is non-preemptive; SRTF is preemptive.</p></section><section><div class="panel"><h3>Animated Gantt timeline</h3><div id="cpu-viz"></div></div><div class="panel"><h3>Live execution & ready queue</h3><div id="cpu-live"></div></div><div class="panel"><h3>Performance results</h3><div id="cpu-results"></div></div></section></div>`;$('#cpu-input').innerHTML=cpuRows.map((p,i)=>`<tr><td>${esc(p.id)}</td>${['arrival','burst','priority'].map(k=>`<td><input aria-label="${k} ${p.id}" type="number" value="${p[k]}" onchange="cpuRows[${i}].${k}=Number(this.value)"></td>`).join('')}<td><button class="btn small" onclick="cpuRows.splice(${i},1);renderCPU()">×</button></td></tr>`).join('');drawCPU()}
function runCPU(){try{stop();cpuResult=cpuCompute(cpuRows,cpuAlg,quantum);cpuStep=0;drawCPU();toast(`${cpuAlg} simulation started`);setTimeout(()=>{if(cpuResult&&cpuStep===0)play('cpu')},350)}catch(e){toast(e.message)}}
function drawCPU(){if(!$('#cpu-viz'))return;if(!cpuResult){$('#cpu-viz').innerHTML='<div class="empty">Configure railway processes and select Start simulation. Playback begins automatically; pause or step through it at any time.</div>';$('#cpu-live').innerHTML='<p class="note">Playback controls will appear after simulation.</p>';$('#cpu-results').innerHTML='';return}const d=cpuResult,s=d.steps[cpuStep],colors=['#7EC4C3','#9BA8AB','#D5C19A','#83A8C6','#B7A4C4','#A5B99D'];const used=d.gantt.slice(0,s.time);const merged=[];used.forEach(g=>{let last=merged[merged.length-1];if(last&&last.id===g.id)last.end=g.end;else merged.push({...g})});$('#cpu-viz').innerHTML=`<div class="timeline">${merged.map(g=>`<div class="segment" style="width:${Math.max(55,(g.end-g.start)*42)}px;background:${g.id==='Idle'?'#62747a':colors[d.jobs.findIndex(j=>j.id===g.id)%colors.length]}" data-end="${g.end}">${g.id}<small>${g.start}</small></div>`).join('')}</div>${controls('cpu',cpuStep,d.steps.length-1)}<div class="stepnote">${esc(s.note)}</div>`;$('#cpu-live').innerHTML=`<div class="metric-row"><div class="metric"><small>Clock</small><b>${s.time}</b></div><div class="metric"><small>CPU</small><b>${esc(s.active||'—')}</b></div><div class="metric"><small>Ready queue</small><b style="font-size:16px">${esc(s.queue.join(' → ')||'Empty')}</b></div></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Process</th><th>Remaining burst</th></tr></thead><tbody>${d.jobs.map((j,i)=>`<tr><td>${j.id}</td><td>${s.remaining[i]}</td></tr>`).join('')}</tbody></table></div>`;$('#cpu-results').innerHTML=cpuStep<d.steps.length-1?`<div class="empty"><strong>Calculating results…</strong><p class="sub">The completion, turnaround, waiting and response-time table appears when execution finishes.</p><div class="progress-track"><span style="width:${Math.round(cpuStep/(d.steps.length-1)*100)}%"></span></div></div>`:`<div class="result-reveal"><div class="eyebrow">EXECUTION COMPLETE</div><div class="metric-row"><div class="metric"><small>Avg waiting</small><b>${d.avgWait.toFixed(2)}</b></div><div class="metric"><small>Avg turnaround</small><b>${d.avgTat.toFixed(2)}</b></div><div class="metric"><small>Total time</small><b>${d.steps.at(-1).time}</b></div></div><div class="table-wrap"><table><thead><tr><th>Process</th><th>CT</th><th>TAT</th><th>WT</th><th>RT</th></tr></thead><tbody>${d.jobs.map(j=>`<tr><td>${j.id}</td><td>${j.completion}</td><td>${j.turnaround}</td><td>${j.waiting}</td><td>${j.response}</td></tr>`).join('')}</tbody></table></div></div>`}
function saveCPU(){if(!cpuResult)return toast('Simulate first');store.put({type:'cpu',algorithm:cpuAlg,input:{rows:cpuRows,quantum},summary:`Average waiting: ${cpuResult.avgWait.toFixed(2)} | Turnaround: ${cpuResult.avgTat.toFixed(2)}`})}
function bankerCompute(alloc,max,avail){const n=alloc.length,m=avail.length;if(n<1||n>12||m<1||m>8)throw Error('Supports 1–12 processes and 1–8 resources');if([...alloc.flat(),...max.flat(),...avail].some(v=>!Number.isInteger(v)||v<0))throw Error('Resource counts must be nonnegative integers');if(alloc.some((r,i)=>r.length!==m||max[i].length!==m||r.some((v,j)=>v>max[i][j])))throw Error('Allocation cannot exceed Maximum; all rows must have matching dimensions');const need=alloc.map((r,i)=>r.map((v,j)=>max[i][j]-v));let work=avail.slice(),finished=Array(n).fill(false),sequence=[],steps=[{work:work.slice(),finished:finished.slice(),selected:null,note:'Safety check starts. Work = Available. Finish is false for every process.'}];while(sequence.length<n){let idx=need.findIndex((row,i)=>!finished[i]&&row.every((v,j)=>v<=work[j]));if(idx<0)break;const before=work.slice();work=work.map((v,j)=>v+alloc[idx][j]);finished[idx]=true;sequence.push(idx);steps.push({work:work.slice(),finished:finished.slice(),selected:idx,note:`P${idx} can complete because Need [${need[idx]}] ≤ Work [${before}]. Release Allocation [${alloc[idx]}] → Work [${work}].`})}const safe=sequence.length===n;steps.push({work:work.slice(),finished:finished.slice(),selected:null,note:safe?`SAFE STATE. Safe sequence: ${sequence.map(i=>'P'+i).join(' → ')}.`:`UNSAFE STATE. No unfinished process has Need ≤ Work [${work}]. This does not necessarily mean deadlock has already occurred.`});return {steps,need,safe,sequence}}
function renderBanker(){stop();const n=allocation.length,m=available.length;$('#content').innerHTML=`<h1 class="page-title">Banker's Algorithm Simulator</h1><p class="sub">Check whether railway booking and payment tasks can receive database/payment-service resources safely.</p><div class="tabs"><button class="tab ${bankMode==='safety'?'active':''}" onclick="bankMode='safety';renderBanker()">Safety algorithm</button><button class="tab ${bankMode==='request'?'active':''}" onclick="bankMode='request';renderBanker()">Resource request</button></div><div class="sim-grid"><section class="panel"><h3>Resource allocation configuration</h3><div class="fields"><div class="field"><label>Processes</label><input type="number" min="1" max="12" value="${n}" onchange="resizeBank(+this.value,available.length)"></div><div class="field"><label>Resource types</label><input type="number" min="1" max="8" value="${m}" onchange="resizeBank(allocation.length,+this.value)"></div></div><div class="matrix-group" style="margin-top:16px"><div><div class="matrix-title">Allocation</div><div id="bank-alloc" class="matrix"></div></div><div><div class="matrix-title">Maximum</div><div id="bank-max" class="matrix"></div></div></div><div class="matrix-title">Available resources</div><div id="bank-avail" class="matrix"></div>${bankMode==='request'?`<div class="matrix-title">New request</div><div class="field"><label>Requesting process</label><select id="request-process">${allocation.map((_,i)=>`<option value="${i}">P${i}</option>`).join('')}</select></div><div id="bank-request" class="matrix" style="margin-top:10px"></div>`:''}<div class="action-row"><button class="btn primary" onclick="${bankMode==='safety'?'runBanker()':'requestBanker()'}">▶ ${bankMode==='safety'?'Check safety':'Evaluate request'}</button><button class="btn" onclick="saveBanker()">Save run</button><button class="btn" onclick="resetBanker()">Load example</button></div></section><section><div class="panel"><h3>Need matrix (Maximum − Allocation)</h3><div id="bank-need"></div></div><div class="panel"><h3>Step-by-step safety evaluation</h3><div id="bank-viz"></div></div><div class="panel"><h3>Safety result</h3><div id="bank-result"></div></div></section></div>`;function matrix(id,data,kind){$(id).innerHTML=data.map((row,i)=>`<div class="matrix-row"><span class="rowname">${kind==='available'?'A':`P${i}`}</span>${row.map((v,j)=>`<input type="number" min="0" value="${v}" aria-label="${kind} ${i} ${j}" onchange="${kind==='available'?`available[${j}]`:`${kind==='allocation'?'allocation':'maximum'}[${i}][${j}]`}=Number(this.value);bankResult=null;drawBanker()">`).join('')}</div>`).join('')};matrix('#bank-alloc',allocation,'allocation');matrix('#bank-max',maximum,'maximum');matrix('#bank-avail',[available],'available');if(bankMode==='request')$('#bank-request').innerHTML=`<div class="matrix-row"><span class="rowname">R</span>${available.map((_,j)=>`<input id="req-${j}" type="number" min="0" value="0" aria-label="Request resource ${j}">`).join('')}</div>`;drawBanker()}
function resizeBank(n,m){if(!Number.isInteger(n)||n<1||n>12||!Number.isInteger(m)||m<1||m>8)return toast('Use 1–12 processes and 1–8 resources');allocation=Array.from({length:n},(_,i)=>Array.from({length:m},(_,j)=>allocation[i]?.[j]||0));maximum=Array.from({length:n},(_,i)=>Array.from({length:m},(_,j)=>Math.max(allocation[i][j],maximum[i]?.[j]||0)));available=Array.from({length:m},(_,j)=>available[j]||0);bankResult=null;renderBanker()}
