// Memory Management: generate immutable snapshots so every allocation can be inspected and replayed.
let memMode='fixed',memTotal=1024,memParts=[1,1,1,1],memProcesses=[{name:'Process 1',size:130},{name:'Process 2',size:250},{name:'Process 3',size:100},{name:'Process 4',size:115}],memStrategy='first',memResult=null,memStep=0;
