function runMemory(){try{stop();memResult=memoryCompute();memStep=0;drawMemory();toast('Memory allocation animation started');setTimeout(()=>{if(memResult&&memStep===0)play('memory')},350)}catch(e){toast(e.message)}}
function renderMemory(){stop();$('#content').innerHTML=`<h1 class="page-title">Memory Management Simulator</h1><p class="sub">Railway booking and payment processes request memory. Watch each allocation happen step by step.</p><div class="tabs">${['fixed','variable'].map(m=>`<button class="tab ${memMode===m?'active':''}" onclick="memMode='${m}';memResult=null;renderMemory()">${m==='fixed'?'Fixed Partitioning':'Variable Partitioning'}</button>`).join('')}</div><div class="sim-grid"><section class="panel"><h3>Memory configuration</h3><div class="field"><label>Total memory (KB)</label><input type="number" min="64" value="${memTotal}" onchange="memTotal=Math.max(64,+this.value||64);memResult=null"></div>${memMode==='fixed'?`<div class="field" style="margin-top:10px"><label>Number of equal-sized partitions</label><input type="number" min="1" max="${memTotal}" value="${memParts.length}" onchange="memParts=Array.from({length:Math.max(1,Math.min(${memTotal},Math.floor(+this.value||1)))},()=>1);memResult=null;renderMemory()"></div><p class="note">All partitions are equal-sized: ${memTotal} KB ÷ ${memParts.length} partitions = ${memTotal/memParts.length} KB each. Each partition holds at most one process; unused space inside an allocated partition is internal fragmentation.</p>`:`<p class="note">Variable partitioning starts with one contiguous free region of ${memTotal} KB. Each process receives a differently sized block matching its request; the remaining free region is split after each allocation. Releasing processes can create separate holes and external fragmentation.</p>`}<div class="field" style="margin-top:10px"><label>Placement strategy</label><select onchange="memStrategy=this.value;memResult=null"><option value="first" ${memStrategy==='first'?'selected':''}>First Fit</option><option value="best" ${memStrategy==='best'?'selected':''}>Best Fit</option><option value="worst" ${memStrategy==='worst'?'selected':''}>Worst Fit</option></select></div><h3 style="margin-top:20px">Railway processes (KB)</h3><div class="table-wrap"><table><thead><tr><th>Process</th><th>Request</th><th></th></tr></thead><tbody>${memProcesses.map((p,i)=>`<tr><td><input value="${esc(p.name)}" onchange="memProcesses[${i}].name=this.value;memResult=null"></td><td><input type="number" min="1" value="${p.size}" onchange="memProcesses[${i}].size=+this.value;memResult=null"></td><td><button class="btn small" onclick="memProcesses.splice(${i},1);memResult=null;renderMemory()">×</button></td></tr>`).join('')}</tbody></table></div><div class="action-row"><button class="btn small" onclick="memProcesses.push({name:'P'+(memProcesses.length+1),size:128});memResult=null;renderMemory()">+ Add process</button><button class="btn small" onclick="memProcesses=[{name:'Process 1',size:130},{name:'Process 2',size:250},{name:'Process 3',size:100},{name:'Process 4',size:115}];memTotal=1024;memParts=[1,1,1,1];memStrategy='first';memResult=null;renderMemory()">Load case-study example</button><button class="btn primary" onclick="runMemory()">▶ Start allocation</button><button class="btn" onclick="saveMemory()">Save run</button></div></section><section><div class="panel"><h3>Animated memory map</h3><div id="memory-viz"></div></div><div class="panel"><h3>Allocation ledger</h3><div id="memory-ledger"></div></div><div class="panel"><h3>Fragmentation & summary</h3><div id="memory-metrics"></div></div></section></div><section class="panel"><h3>How the algorithm works</h3><pre class="pseudocode"><code>${memMode==='fixed'?`partition_size = total_memory / partition_count
for each process in arrival order:
  find a free partition large enough
  select partition using First / Best / Worst Fit
  allocate the entire partition
  internal_fragmentation = partition_size - process_size
  if no suitable partition: allocation fails`:`for each process in arrival order:
  find a free hole large enough
  select hole using First / Best / Worst Fit
  allocate requested size and split remaining hole
  if no suitable hole: allocation fails
external fragmentation can leave free space in separate holes`}</code></pre></section>`;drawMemory()}
function drawMemory(){if(!$('#memory-viz'))return;if(!memResult){$('#memory-viz').innerHTML='<div class="empty">Choose a partitioning method and allocation strategy, then start. Memory blocks animate one process at a time.</div>';$('#memory-ledger').innerHTML='';$('#memory-metrics').innerHTML='';return}const d=memResult,s=d.steps[memStep];const total=memMode==='fixed'?memTotal:memTotal;$('#memory-viz').innerHTML=`<div class="memory-mode-banner"><strong>${memMode==='fixed'?'FIXED PARTITIONING':'VARIABLE PARTITIONING'}</strong><span>${memMode==='fixed'?'Equal-sized predefined partitions · one process per partition':'Dynamic-sized blocks · split free holes on allocation'}</span></div><div class="memory-map">${s.blocks.map((b,i)=>`<div class="memory-block ${b.free?'free-block':'used-block'} ${s.active&&b.process===s.active?'active-block':''}" style="flex:${Math.max(1,b.size)}"><small>${esc(b.id)}</small><strong>${b.free?'FREE':esc(b.process)}</strong><span>${b.size} KB</span></div>`).join('')}</div><div class="memory-scale"><span>0 KB</span><span>${total} KB total capacity</span></div>${controls('memory',memStep,d.steps.length-1)}<div class="stepnote"><strong>${s.active?`Current process: ${esc(s.active)}`:'Simulation summary'}</strong><br>${esc(s.note)}</div>`;$('#memory-ledger').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Process</th><th>Request</th><th>Status</th><th>Partition/block</th><th>Internal waste</th></tr></thead><tbody>${s.results.map(r=>`<tr class="${r.proc===s.active?'active-row':''}"><td>${esc(r.proc)}</td><td>${r.size} KB</td><td>${r.placed?'Allocated':'Failed'}</td><td>${r.placed?esc(r.block):'—'}</td><td>${r.placed?r.waste+' KB':'—'}</td></tr>`).join('')||'<tr><td colspan="5">No process has been allocated yet.</td></tr>'}</tbody></table></div>`;const allocated=s.results.filter(r=>r.placed).reduce((sum,r)=>sum+r.size,0),internal=s.results.reduce((sum,r)=>sum+r.waste,0),free=s.blocks.filter(b=>b.free).reduce((sum,b)=>sum+b.size,0),largest=Math.max(0,...s.blocks.filter(b=>b.free).map(b=>b.size));$('#memory-metrics').innerHTML=`<div class="metric-row"><div class="metric"><small>Requested memory allocated</small><b>${allocated} KB</b></div><div class="metric"><small>Internal fragmentation</small><b>${internal} KB</b></div><div class="metric"><small>Free memory</small><b>${free} KB</b></div><div class="metric"><small>Failed requests</small><b>${s.results.filter(r=>!r.placed).length}</b></div></div><p class="note">${memMode==='fixed'?'Fixed partitioning can leave internal fragmentation inside allocated partitions.':'Variable partitioning allocates exact request sizes. External fragmentation can arise when released memory forms separate holes. The largest current free hole is '+largest+' KB.'}</p>`}
function saveMemory(){try{const r=memResult||memoryCompute();store.put({type:'memory',algorithm:`Memory Management · ${memMode} · ${memStrategy}`,input:{memMode,memTotal,memParts,memProcesses,memStrategy},summary:`${r.results.filter(x=>x.placed).length}/${r.results.length} processes allocated`})}catch(e){toast(e.message)}}
function renderHistory(){const h=store.get();$('#content').innerHTML=`<h1 class="page-title">Simulation history</h1><p class="sub">Your saved experiments live on this device. Reopen an input set or export your runs.</p><div class="action-row"><button class="btn primary" onclick="exportHistory()">↓ Export CSV</button><button class="btn" onclick="if(confirm('Delete all saved simulations?')){store.clear();renderHistory()}">Clear history</button></div><div class="panel" id="history-list">${h.length?h.map(x=>`<div class="history-item"><div><strong>${esc(x.algorithm)}</strong><small>${new Date(x.date).toLocaleString()} · ${esc(x.summary)}</small></div><div class="action-row"><button class="btn small" onclick="reopen(${x.id})">↗ Reopen</button><button class="btn small" onclick="removeHistory(${x.id})">×</button></div></div>`).join(''):'<div class="empty">No simulations saved yet. Complete a simulation and choose Save run.</div>'}</div>`}
function removeHistory(id){localStorage.setItem(key,JSON.stringify(store.get().filter(x=>x.id!==id)));renderHistory()}
function reopen(id){const x=store.get().find(x=>x.id===id);if(!x)return;if(x.type==='cpu'){cpuAlg=x.algorithm;cpuRows=x.input.rows.map(r=>({...r}));quantum=x.input.quantum;cpuResult=null;location.hash='#/cpu'}else if(x.type==='memory'){memMode=x.input.memMode;memTotal=x.input.memTotal;memParts=x.input.memParts;memProcesses=x.input.memProcesses;memStrategy=x.input.memStrategy;memResult=null;location.hash='#/memory'}else if(x.type==='sync'){syncBufferSize=x.input.syncBufferSize;syncBuffer=x.input.syncBuffer;syncProduced=x.input.syncProduced;syncConsumed=x.input.syncConsumed;syncResult=null;syncLog=[];location.hash='#/sync'}else{allocation=x.input.allocation.map(r=>r.slice());maximum=x.input.maximum.map(r=>r.slice());available=x.input.available.slice();bankResult=null;bankMode='safety';location.hash='#/banker'}route()}
function exportHistory(){const h=store.get();if(!h.length)return toast('No history to export');const csv=[['Date','Algorithm','Summary','Input JSON'],...h.map(x=>[x.date,x.algorithm,x.summary,JSON.stringify(x.input)])].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='algobuzz-history.csv';a.click();URL.revokeObjectURL(url)}

const questions=[{q:'Which scheduling algorithm uses a fixed time quantum?',a:['FCFS','Round Robin','SJF','SRTF'],correct:1,why:'Round Robin preempts a process when its time quantum expires.'},{q:'What does a safe state mean in Banker’s Algorithm?',a:['No processes exist','There is an order in which all processes can finish','Every request must be granted','Deadlock has already occurred'],correct:1,why:'A safe sequence shows a possible completion order for every process.'},{q:'In Producer–Consumer, what does the empty semaphore count?',a:['Items currently in the buffer','Available empty slots','Number of consumers','Locked processes'],correct:1,why:'The empty semaphore tracks available slots in the bounded buffer.'},{q:'What is turnaround time?',a:['Completion − Arrival','Burst − Arrival','Waiting − Completion','Arrival + Priority'],correct:0,why:'Turnaround time measures elapsed time from arrival to completion.'},{q:'Which mechanism protects the critical section in Producer–Consumer?',a:['Page table','Mutex','Partition table','Gantt chart'],correct:1,why:'A mutex ensures only one process at a time accesses the critical section.'},{q:'What is internal fragmentation?',a:['Free memory between allocated blocks','Unused space inside an allocated partition','A CPU scheduling delay','A deadlock condition'],correct:1,why:'Fixed-size partitions can leave unused space inside an allocated partition.'},{q:'Which allocation strategy selects the smallest suitable free block?',a:['First Fit','Best Fit','Worst Fit','Round Robin'],correct:1,why:'Best Fit chooses the smallest block that can satisfy the process.'},{q:'What happens when a producer finds a full bounded buffer?',a:['It overwrites an item','It must wait','It clears the buffer','It increases the buffer automatically'],correct:1,why:'The producer waits until a consumer frees a slot.'}];
function renderQuiz(){const q=questions[quizIndex];$('#content').innerHTML=`<h1 class="page-title">Knowledge check</h1><p class="sub">Test your operating systems fundamentals with instant feedback.</p><section class="panel" style="max-width:760px"><div class="eyebrow">${quizIndex<questions.length?`QUESTION ${quizIndex+1} OF ${questions.length}`:'QUIZ COMPLETE'}</div>${q?`<h2>${esc(q.q)}</h2><div>${q.a.map((a,i)=>`<button class="answer ${quizChoice===i?'chosen':''}" onclick="chooseAnswer(${i})" ${quizAnswered?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(a)}</button>`).join('')}</div>${quizAnswered?`<div class="stepnote">${quizChoice===q.correct?'✓ Correct!':'✕ Not quite.'} ${esc(q.why)}</div><div class="action-row"><button class="btn primary" onclick="quizIndex++;quizChoice=null;quizAnswered=false;renderQuiz()">${quizIndex===questions.length-1?'See results':'Next question →'}</button></div>`:''}`:`<h2>You scored ${quizScore} / ${questions.length}</h2><p class="sub">${quizScore>=6?'Great work. Keep exploring the simulators.':'Review the simulator concepts and try again.'}</p><button class="btn primary" onclick="quizIndex=0;quizScore=0;quizChoice=null;quizAnswered=false;renderQuiz()">↺ Try again</button>`}</section>`}
function chooseAnswer(i){if(quizAnswered)return;quizChoice=i;quizAnswered=true;if(i===questions[quizIndex].correct)quizScore++;renderQuiz()}
